import numpy as np
from sklearn.preprocessing import MinMaxScaler
import pandas as pd

def task_func(df: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame):
        raise TypeError("Input must be a pandas DataFrame.")

    if df.empty:
        raise ValueError("DataFrame must not be empty.")

    if df.isna().any().any():
        raise ValueError("DataFrame must not contain NaN values.")

    if len(df.select_dtypes(include='number').columns) != len(df.columns):
        raise TypeError("DataFrame must contain only numeric data types.")

    cumulative = df.cumsum()
    scaled = MinMaxScaler().fit_transform(cumulative)

    return pd.DataFrame(scaled, columns=df.columns, index=df.index)
